import type { Metadata } from "next";

import { SITE_NAME } from "@/lib/site";

/** The full title shown in search results and link previews. */
export const DEFAULT_TITLE = `${SITE_NAME} — Närvaro i riksdagen`;

/** Link preview image, generated by app/og.png/route.tsx. */
export const OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: DEFAULT_TITLE,
};

/** Open Graph fields every page shares. */
export const OG_DEFAULTS = {
  type: "website",
  locale: "sv_SE",
  siteName: SITE_NAME,
  images: [OG_IMAGE],
} satisfies NonNullable<Metadata["openGraph"]>;

interface PageMetadataInput {
  /** Page title without the site name; omit for the start page */
  title?: string;
  description: string;
  /** Root-relative path with the trailing slash the export uses, e.g. "/partier/" */
  path: string;
}

/**
 * Title, description, canonical URL and a complete Open Graph block. Next.js
 * replaces a parent's `openGraph` instead of merging it, so every page needs
 * the whole block. Relative URLs resolve against `metadataBase` (layout).
 */
export function pageMetadata({ title, description, path }: PageMetadataInput): Metadata {
  if (!path.startsWith("/") || !path.endsWith("/")) {
    throw new Error(`Page path must start and end with "/": ${path}`);
  }
  return {
    ...(title !== undefined && { title }),
    description,
    alternates: { canonical: path },
    openGraph: {
      ...OG_DEFAULTS,
      url: path,
      title: title === undefined ? DEFAULT_TITLE : `${title} — ${SITE_NAME}`,
      description,
    },
  };
}
